require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['especialista'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$id=(int)$_SESSION['usuario']['id_usuario'];$contar=function(string $cond='')use($pdo,$id){$q=$pdo->prepare('SELECT COUNT(*) FROM reparaciones WHERE id_especialista=?'.($cond?' AND '.$cond:''));$q->execute([$id]);return(int)$q->fetchColumn();};$q=$pdo->prepare('SELECT r.*,s.marca,s.modelo,s.problema_reportado,u.nombre AS cliente FROM reparaciones r JOIN solicitudes s ON s.id_solicitud=r.id_solicitud JOIN usuarios u ON u.id_usuario=s.id_cliente WHERE r.id_especialista=? ORDER BY r.id_reparacion DESC');$q->execute([$id]);$reparaciones=$q->fetchAll();$titulo_pagina='Panel especialista';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
